/**
 * Reusable VELLUM brand mark.
 *
 * Uses the original transparent PNG embedded as a data URI so every app
 * (dashboard, admin, docs) renders the identical asset regardless of Vite
 * `base` paths or public-directory copying.
 */

const VELLUM_MARK_DATA_URI =
  "data:image/png;base64," +
  "";

export interface VellumLogoProps {
  /** Rendered width/height in pixels. Defaults to 24. */
  readonly size?: number;
  /** Additional class names on the wrapping span. */
  readonly className?: string;
  /** Accessible label. Pass `null` for decorative usage inside a labelled parent. */
  readonly label?: string | null;
}

export function VellumLogo({ size = 24, className, label = "VELLUM" }: VellumLogoProps) {
  return (
    <img
      src={VELLUM_MARK_DATA_URI}
      width={size}
      height={size}
      alt={label ?? ""}
      role={label === null ? "presentation" : "img"}
      className={className}
      style={{ display: "inline-block", flexShrink: 0, objectFit: "contain" }}
    />
  );
}
